    public static <T extends Block> T registerBlock(T block) {
        IColorListener listener;
        IAutoCreator creator;
        BlockItem item;
        ForgeRegistries.BLOCKS.register(((IRegistryProvider)block).getRegistryName(), block);
        if (block instanceof IAutoCreator && (item = (creator = (IAutoCreator)block).createItem()) != null) {
            if (item instanceof IRegistryProvider) {
                IRegistryProvider registry = (IRegistryProvider)item;
                IC2Items.registerItem(item, registry.getRegistryName());
            } else {
                IC2Items.registerItem(item, ((IRegistryProvider)block).getRegistryName());
            }
        }
        if (block instanceof IToolProvider) {
            IToolProvider provider = (IToolProvider)block;
            provider.registerTools();
        }
        if (block instanceof IColorListener && (listener = (IColorListener)block).needsColoring()) {
            COLORABLE.add(block);
        }
        return block;
    }

